"""Generated grid: dorm calm warning reg. Cross-verified cell by cell at emit time.

Failure-Class: FC-retention-contention-chain-collides-inside-armed-storm-window

Each test re-drives its cell through the real boundary
(``drive_cell``) and compares the full observable freeze against the
literal the emit-time cross-verify produced; the independent model walk and
the emitter live outside the tree. Do not edit frozen literals by hand.
"""

from tests.unit.batch_retention_storm_gate_grid_harness import drive_cell


def _drive(monkeypatch, caplog, **params):
    return drive_cell(monkeypatch, caplog, **params)


def test_f_abz_enz_rsa_wvz_gnz(monkeypatch, caplog) -> None:
    assert _drive(
        monkeypatch,
        caplog,
        label='batch_artifact_register',
        entry_wait=0.0,
        residual_schedule=(0.0,),
        wave_wait=0.0,
        generation=0,
        hostile_peek=False,
        damper_mode='dormant_none',
        log_mode='warning',
    ) == {
        'result': 'retained',
        'raised': None,
        'retry_after': 0.0,
        'body_calls': [1],
        'sleeps': [],
        'damper_slept': [],
        'events': [],
        'note_success': [],
        'consult_count': 0,
        'peek_count': 0,
        'records': [],
    }


